    "components.imsettingssection.378eaca774bb": "Sign in via QR scan",
    "components.imsettingssection.390c8b791bcd": "Scan with the Feishu mobile app → confirm creation on the opened page → App ID/Secret are fetched automatically and connected (the app owner is bound as the owner). If you'd rather not scan, enter credentials manually under Advanced configuration.",
