    "components.imsettingssection.4a151de9633d": "The bot stays online while the desktop app runs: a Feishu Open Platform custom app (long-connection event subscription, no public endpoint needed). Incoming messages go straight to OH, replies are sent back the same way; attachments are archived to the cloud drive afterwards.",
