    "components.ohsettingspage.d09e846cd4ab": "In System Settings → Apps → App launch management, set OneTHU to “Manage manually” and allow auto-launch, associated launch, and background activity; then add OneTHU to the battery-optimization whitelist. Only after this will the floating ball and voice keep running in the background instead of being killed by the system. {value}",
